CREATE TABLE "AiConversation" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"userId" TEXT NOT NULL,"title" TEXT NOT NULL DEFAULT 'New conversation',"provider" TEXT NOT NULL,"model" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AiConversation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiMessage" ("id" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"role" TEXT NOT NULL,"content" TEXT NOT NULL,"inputTokens" INTEGER,"outputTokens" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AiMessage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiUsage" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"userId" TEXT NOT NULL,"provider" TEXT NOT NULL,"model" TEXT NOT NULL,"inputTokens" INTEGER NOT NULL DEFAULT 0,"outputTokens" INTEGER NOT NULL DEFAULT 0,"estimatedCost" DECIMAL(12,6),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AiUsage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationPreference" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"inApp" BOOLEAN NOT NULL DEFAULT true,"email" BOOLEAN NOT NULL DEFAULT true,"taskReminders" BOOLEAN NOT NULL DEFAULT true,"projectUpdates" BOOLEAN NOT NULL DEFAULT true,"invoiceReminders" BOOLEAN NOT NULL DEFAULT true,"workspaceInvitations" BOOLEAN NOT NULL DEFAULT true,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NotificationPreference_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FileAsset" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"uploaderId" TEXT NOT NULL,"originalName" TEXT NOT NULL,"storageName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"sizeBytes" INTEGER NOT NULL,"checksum" TEXT NOT NULL,"entityType" TEXT,"entityId" TEXT,"deletedAt" TIMESTAMP(3),"purgeAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "FileAsset_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "NotificationPreference_userId_key" ON "NotificationPreference"("userId");
CREATE UNIQUE INDEX "FileAsset_storageName_key" ON "FileAsset"("storageName");
CREATE INDEX "AiConversation_workspaceId_userId_updatedAt_idx" ON "AiConversation"("workspaceId","userId","updatedAt");
CREATE INDEX "AiMessage_conversationId_createdAt_idx" ON "AiMessage"("conversationId","createdAt");
CREATE INDEX "AiUsage_workspaceId_createdAt_idx" ON "AiUsage"("workspaceId","createdAt");
CREATE INDEX "AiUsage_userId_createdAt_idx" ON "AiUsage"("userId","createdAt");
CREATE INDEX "FileAsset_workspaceId_deletedAt_createdAt_idx" ON "FileAsset"("workspaceId","deletedAt","createdAt");
CREATE INDEX "FileAsset_entityType_entityId_idx" ON "FileAsset"("entityType","entityId");
ALTER TABLE "AiConversation" ADD CONSTRAINT "AiConversation_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AiConversation" ADD CONSTRAINT "AiConversation_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AiMessage" ADD CONSTRAINT "AiMessage_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "AiConversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "NotificationPreference" ADD CONSTRAINT "NotificationPreference_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FileAsset" ADD CONSTRAINT "FileAsset_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FileAsset" ADD CONSTRAINT "FileAsset_uploaderId_fkey" FOREIGN KEY ("uploaderId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
